// Shared shapes. Changes here touch every stage, so keep them deliberate.

export type Verdict = "keep" | "revert" | "stale" | "freeze";

/** How one `entire graph verify` run reads, reduced to what a decision can use. */
export type VerifyOutcome = "holds" | "regression" | "unknown";

export interface VerifyResult {
  outcome: VerifyOutcome;
  /** The `VERDICT:` line exactly as printed. It goes in the ledger and the PR. */
  line: string;
  newlyFailing: string[];
  /** verify could not parse the runner and fell back to the exit code. Never revert on this. */
  exitCodeOnly: boolean;
}

/** The exam: how to run the tests and which files count as the tests. */
export interface ExamConfig {
  /** Test command, run by verify inside each worktree. */
  test: string;
  /** Run before verify in each worktree, e.g. `npm ci`. A failure here is a replay env failure. */
  setup?: string;
  /** Git pathspec globs for test files, test config and snapshots. */
  exam: string[];
}

export interface ReplayResult {
  commit: string;
  parent: string;
  exam: string;
  /** The parent's own tests on the parent's code. */
  baseline: string;
  /** The commit's tests on the commit's code. What CI would say. */
  asCommitted: VerifyResult;
  /** Exam files the commit added, modified or deleted. */
  examFilesChanged: string[];
  attempts: number;
}

export interface Decision {
  verdict: Verdict;
  reason: string;
}

/** A replay could not run (setup failed, verify crashed). Retry once, then freeze. */
export class ReplayEnvError extends Error {
  readonly stage: string;
  constructor(stage: string, message: string) {
    super(`${stage}: ${message}`);
    this.name = "ReplayEnvError";
    this.stage = stage;
  }
}

import { spawn } from "node:child_process";

export interface ExecResult {
  code: number;
  stdout: string;
  stderr: string;
  timedOut: boolean;
}

interface ExecOptions {
  cwd?: string;
  timeoutMs?: number;
  /** Run `cmd` through the shell. Only for operator-configured test and setup commands. */
  shell?: boolean;
}

/** Run a process to completion. Never throws on a non-zero exit; callers decide what failure means. */
export function exec(cmd: string, args: string[], opts: ExecOptions = {}): Promise<ExecResult> {
  return new Promise((resolve, reject) => {
    const child = spawn(cmd, args, {
      cwd: opts.cwd,
      shell: opts.shell ?? false,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    child.stdout.on("data", (d) => (stdout += d));
    child.stderr.on("data", (d) => (stderr += d));
    const timer = opts.timeoutMs
      ? setTimeout(() => {
          timedOut = true;
          child.kill("SIGKILL");
        }, opts.timeoutMs)
      : undefined;
    child.on("error", reject);
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code: code ?? -1, stdout, stderr, timedOut });
    });
  });
}

/** Like exec, but a non-zero exit is an error. For git plumbing that must succeed. */
export async function execOk(cmd: string, args: string[], opts: ExecOptions = {}): Promise<string> {
  const r = await exec(cmd, args, opts);
  if (r.code !== 0) {
    throw new Error(`${cmd} ${args.join(" ")} exited ${r.code}: ${r.stderr.trim() || r.stdout.trim()}`);
  }
  return r.stdout;
}

import { execOk } from "./exec.ts";

const git = (repo: string, ...args: string[]) => execOk("git", ["-C", repo, ...args]);

export async function resolveSha(repo: string, rev: string): Promise<string> {
  return (await git(repo, "rev-parse", "--verify", `${rev}^{commit}`)).trim();
}

/** First parent. Revenant audits linear agent commits; merges are frozen upstream of this. */
export async function parentOf(repo: string, sha: string): Promise<string> {
  return resolveSha(repo, `${sha}^1`);
}

export async function addWorktree(repo: string, path: string, sha: string): Promise<void> {
  await git(repo, "worktree", "add", "--force", "--detach", path, sha);
}

export async function removeWorktree(repo: string, path: string): Promise<void> {
  await git(repo, "worktree", "remove", "--force", path).catch(() => undefined);
}

export async function pruneWorktrees(repo: string): Promise<void> {
  await git(repo, "worktree", "prune");
}

export interface ChangedFile {
  status: "A" | "M" | "D" | string;
  path: string;
}

/** Files a commit changed, limited to the given pathspec globs. Renames show as delete plus add. */
export async function changedFiles(
  repo: string,
  parent: string,
  sha: string,
  globs: string[],
): Promise<ChangedFile[]> {
  const pathspecs = globs.map((g) => `:(glob)${g}`);
  const out = await git(repo, "diff", "--name-status", "--no-renames", parent, sha, "--", ...pathspecs);
  return out
    .split("\n")
    .filter(Boolean)
    .map((line) => {
      const [status, path] = line.split("\t");
      return { status, path };
    });
}

import { exec } from "./exec.ts";
import { ReplayEnvError, type VerifyResult } from "../types.ts";

const VERIFY_TIMEOUT_MS = 120_000;

/**
 * Read verify's output. Its exit code is 0 even on a regression, so only the
 * `VERDICT:` line counts. Wording seen in entire-graph 0.4.0:
 *   PASS (exit 0) | NO EFFECT | REGRESSION in N tests: ... | FAIL (exit N)
 * FAIL only appears when the runner was not parsed, so it is exit-code only.
 * Anything unrecognised is "unknown", which downstream becomes a freeze.
 */
export function parseVerify(text: string): VerifyResult {
  const line = text.split("\n").find((l) => l.startsWith("VERDICT:"))?.trim() ?? "";
  const exitCodeOnly = /exit-code only|exit-code-only/.test(text) || /^VERDICT: FAIL\b/.test(line);
  const failingLine = text.split("\n").find((l) => l.startsWith("NEWLY FAILING"));
  const newlyFailing = failingLine
    ? failingLine.replace(/^NEWLY FAILING \(\d+\):\s*/, "").split(/,\s*(?=\.\/)/).filter(Boolean)
    : [];

  let outcome: VerifyResult["outcome"] = "unknown";
  if (!exitCodeOnly) {
    if (/^VERDICT: REGRESSION\b/.test(line)) outcome = "regression";
    else if (/^VERDICT: (PASS|NO EFFECT)\b/.test(line)) outcome = "holds";
  }
  return { outcome, line, newlyFailing, exitCodeOnly };
}

interface VerifyArgs {
  repo: string;
  test: string;
  recordBaseline?: string;
  preEditBaseline?: string;
}

async function runVerify(args: VerifyArgs): Promise<string> {
  const flags = ["graph", "verify", "--repo", args.repo, "--test", args.test];
  if (args.recordBaseline) flags.push("--record-baseline", args.recordBaseline);
  if (args.preEditBaseline) flags.push("--pre-edit-baseline", args.preEditBaseline);
  const r = await exec("entire", flags, { timeoutMs: VERIFY_TIMEOUT_MS });
  if (r.timedOut) throw new ReplayEnvError("verify", `timed out after ${VERIFY_TIMEOUT_MS / 1000}s`);
  if (r.code !== 0) throw new ReplayEnvError("verify", r.stderr.trim() || `exited ${r.code}`);
  return r.stdout;
}

/** Record the pristine-tree result. Returns the `BASELINE RECORDED` line. */
export async function recordBaseline(repo: string, test: string, path: string): Promise<string> {
  const out = await runVerify({ repo, test, recordBaseline: path });
  const line = out.split("\n").find((l) => l.startsWith("BASELINE RECORDED"));
  if (!line) throw new ReplayEnvError("baseline", `no baseline recorded: ${out.trim().slice(0, 200)}`);
  return line.replace(/^BASELINE RECORDED: \S+ /, "").trim();
}

/** Run the tests and diff them against a recorded baseline. */
export async function verifyAgainst(repo: string, test: string, baseline: string): Promise<VerifyResult> {
  const result = parseVerify(await runVerify({ repo, test, preEditBaseline: baseline }));
  if (!result.line) throw new ReplayEnvError("verify", "no VERDICT line in output");
  return result;
}

