import { mkdir, rm } from "node:fs/promises";
import { join } from "node:path";
import { exec } from "./seams/exec.ts";
import { recordBaseline, verifyAgainst } from "./seams/entire.ts";
import { addWorktree, changedFiles, parentOf, pruneWorktrees, removeWorktree, resolveSha } from "./seams/git.ts";
import { step } from "./seams/trace.ts";
import { ReplayEnvError, type ExamConfig, type ReplayResult } from "./types.ts";

const SETUP_TIMEOUT_MS = 180_000;
const MAX_ATTEMPTS = 2;

async function setup(worktree: string, role: string, cfg: ExamConfig, commit: string): Promise<void> {
  if (!cfg.setup) return;
  await step("replay.setup", "TOOL", { "revenant.commit": commit, "revenant.role": role, "revenant.setup": cfg.setup }, async () => {
    const r = await exec(cfg.setup!, [], { cwd: worktree, shell: true, timeoutMs: SETUP_TIMEOUT_MS });
    if (r.code !== 0 || r.timedOut) {
      const why = r.timedOut ? "timed out" : `exited ${r.code}: ${r.stderr.trim().split("\n").slice(-3).join(" | ")}`;
      throw new ReplayEnvError("setup", `${role}: ${why}`);
    }
  });
}

/**
 * One replay attempt. The parent's tests run on the parent's code to record a baseline,
 * then the commit's tests run on the commit's code against that baseline.
 * Both run in scratch worktrees pinned to fixed SHAs, so nothing depends on HEAD.
 */
async function attempt(repo: string, commit: string, parent: string, cfg: ExamConfig, dir: string) {
  const parentTree = join(dir, "parent");
  const commitTree = join(dir, "commit");
  const baselineFile = join(dir, "baseline.json");
  await rm(dir, { recursive: true, force: true });
  await mkdir(dir, { recursive: true });
  try {
    await addWorktree(repo, parentTree, parent);
    await addWorktree(repo, commitTree, commit);
    await setup(parentTree, "parent", cfg, commit);
    await setup(commitTree, "commit", cfg, commit);

    const baseline = await step("replay.baseline", "TOOL", { "revenant.commit": commit, "revenant.parent": parent }, async (span) => {
      const line = await recordBaseline(parentTree, cfg.test, baselineFile);
      span.setAttribute("revenant.baseline", line);
      return line;
    });

    const asCommitted = await step("replay.as_committed", "TOOL", { "revenant.commit": commit }, async (span) => {
      const r = await verifyAgainst(commitTree, cfg.test, baselineFile);
      span.setAttribute("revenant.verdict_line", r.line);
      span.setAttribute("revenant.outcome", r.outcome);
      return r;
    });

    return { baseline, asCommitted };
  } finally {
    await removeWorktree(repo, parentTree);
    await removeWorktree(repo, commitTree);
    await rm(dir, { recursive: true, force: true });
  }
}

export async function replay(repo: string, rev: string, cfg: ExamConfig, workRoot: string): Promise<ReplayResult> {
  const commit = await resolveSha(repo, rev);
  const parent = await parentOf(repo, commit);
  await pruneWorktrees(repo);

  return step("replay", "CHAIN", { "revenant.commit": commit, "revenant.parent": parent, "revenant.exam": cfg.test }, async (span) => {
    const examFilesChanged = (await changedFiles(repo, parent, commit, cfg.exam)).map((f) => `${f.status} ${f.path}`);
    span.setAttribute("revenant.exam_files_changed", examFilesChanged.join(", "));

    for (let n = 1; ; n++) {
      try {
        const { baseline, asCommitted } = await attempt(repo, commit, parent, cfg, join(workRoot, commit.slice(0, 12)));
        span.setAttribute("revenant.attempts", n);
        return { commit, parent, exam: cfg.test, baseline, asCommitted, examFilesChanged, attempts: n };
      } catch (err) {
        if (!(err instanceof ReplayEnvError) || n >= MAX_ATTEMPTS) {
          span.setAttribute("revenant.attempts", n);
          throw err;
        }
        span.addEvent("replay.retry", { "revenant.attempt": n, "revenant.error": err.message });
      }
    }
  });
}

import type { Decision, ReplayResult } from "./types.ts";

/**
 * v1: trust the commit's own tests, as CI does. If they regress against the parent's
 * baseline the commit is wrong; otherwise it stays. This cannot see a commit that
 * edited its own exam, and that blind spot is what v2 exists to close.
 */
export function decideV1(r: ReplayResult): Decision {
  switch (r.asCommitted.outcome) {
    case "regression":
      return { verdict: "revert", reason: `own exam regresses: ${r.asCommitted.line}` };
    case "holds":
      return { verdict: "keep", reason: "own exam holds against the parent baseline" };
    default:
      return { verdict: "freeze", reason: `verify verdict not usable: ${r.asCommitted.line || "none"}` };
  }
}

#!/usr/bin/env node
import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";
import { decideV1 } from "./decide.ts";
import { replay } from "./replay.ts";
import { subjectOf } from "./seams/git.ts";
import { initTracing, shutdownTracing, step } from "./seams/trace.ts";
import { ReplayEnvError, type Decision, type ExamConfig, type ReplayResult } from "./types.ts";

const USAGE = `usage: revenant replay <commit>... --repo <path> [--config <file>] [--json]

Replays each commit against its parent with entire graph verify and prints the verdict.
The exam (test command, setup, exam globs) comes from <repo>/revenant.config.json.`;

const WORK_ROOT = fileURLToPath(new URL("../.revenant/worktrees/", import.meta.url));

function loadConfig(path: string): ExamConfig {
  if (!existsSync(path)) throw new Error(`no exam config at ${path}`);
  const cfg = JSON.parse(readFileSync(path, "utf8")) as ExamConfig;
  if (!cfg.test || !Array.isArray(cfg.exam) || cfg.exam.length === 0) {
    throw new Error(`${path} needs "test" and a non-empty "exam" list`);
  }
  return cfg;
}

function print(subject: string, r: ReplayResult | null, d: Decision): void {
  const row = (k: string, v: string) => console.log(`  ${k.padEnd(18)}${v}`);
  console.log(`\n${(r?.commit ?? "").slice(0, 7)}  ${subject}`);
  if (r) {
    row("parent baseline", r.baseline);
    row("as committed", r.asCommitted.line);
    row("exam files", r.examFilesChanged.join(", ") || "none changed");
    row("attempts", String(r.attempts));
  }
  row("verdict (v1)", `${d.verdict.toUpperCase()}  ${d.reason}`);
}

async function main(): Promise<number> {
  const { values, positionals } = parseArgs({
    allowPositionals: true,
    options: {
      repo: { type: "string" },
      config: { type: "string" },
      json: { type: "boolean", default: false },
      help: { type: "boolean", short: "h", default: false },
    },
  });
  const [command, ...revs] = positionals;
  if (values.help || command !== "replay" || revs.length === 0 || !values.repo) {
    console.error(USAGE);
    return values.help ? 0 : 2;
  }
  if (existsSync(".env")) process.loadEnvFile(".env");

  const repo = resolve(values.repo);
  const cfg = loadConfig(values.config ? resolve(values.config) : resolve(repo, "revenant.config.json"));

  await initTracing();
  try {
    const results = await step("audit", "WORKFLOW", { "revenant.repo": repo, "revenant.mode": "v1", "revenant.commits": revs.length }, async () => {
      const out = [];
      for (const rev of revs) {
        const subject = await subjectOf(repo, rev);
        let r: ReplayResult | null = null;
        let d: Decision;
        try {
          r = await replay(repo, rev, cfg, WORK_ROOT);
          d = decideV1(r);
        } catch (err) {
          if (!(err instanceof ReplayEnvError)) throw err;
          d = { verdict: "freeze", reason: `replay environment failed twice: ${err.message}` };
        }
        if (!values.json) print(subject, r, d);
        out.push({ rev, subject, replay: r, decision: d });
      }
      return out;
    });
    if (values.json) console.log(JSON.stringify(results, null, 2));
    return 0;
  } finally {
    await shutdownTracing();
  }
}

main().then(
  (code) => process.exit(code),
  (err) => {
    console.error(`revenant: ${err instanceof Error ? err.message : err}`);
    process.exit(1);
  },
);

